cd /exercise/all-your-base && cat > all_your_base.h <<'EOF'
#if !defined(ALL_YOUR_BASE_H)
#define ALL_YOUR_BASE_H

#include <vector>

namespace all_your_base {

std::vector<unsigned int> convert(unsigned int input_base,
                                  const std::vector<unsigned int>& digits,
                                  unsigned int output_base);

}  // namespace all_your_base

#endif // ALL_YOUR_BASE_H
EOF
cat > all_your_base.cpp <<'EOF'
#include "all_your_base.h"

#include <stdexcept>

namespace all_your_base {

std::vector<unsigned int> convert(unsigned int input_base,
                                  const std::vector<unsigned int>& digits,
                                  unsigned int output_base) {
    if (input_base < 2 || output_base < 2) {
        throw std::invalid_argument("base must be at least 2");
    }

    unsigned long long value = 0;
    for (unsigned int digit : digits) {
        if (digit >= input_base) {
            throw std::invalid_argument("digit out of range for input base");
        }
        value = value * input_base + digit;
    }

    if (value == 0) {
        return {};
    }

    std::vector<unsigned int> result;
    while (value > 0) {
        result.insert(result.begin(), static_cast<unsigned int>(value % output_base));
        value /= output_base;
    }
    return result;
}

}  // namespace all_your_base
EOF
/aider/benchmark/cpp-test.sh 2>&1 | tail -20

